param([Parameter(Mandatory=$true)][string]$RunPath,[Parameter(Mandatory=$true)][string]$NativeFixtureDirectory,[int[]]$Stages=@(1,2),[switch]$DiagnosticOnly)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$repo=$PSScriptRoot;while(-not [IO.File]::Exists((Join-Path $repo 'bootstrap/tools/verification.ps1'))){$parent=Split-Path $repo -Parent;if(-not $parent -or $parent -eq $repo){throw 'Repository root not found'};$repo=$parent}
. (Join-Path $repo 'bootstrap/tools/verification.ps1');. (Join-Path $repo 'compiler/UBE_Compiler_v3/tests/semantic/native/abi.ps1')
$prior=Get-Content (Join-Path $RunPath 'report.json') -Raw|ConvertFrom-Json;if(-not $prior.success){throw 'A successful whole-checker source snapshot is required'};if(-not $DiagnosticOnly){foreach($identity in $prior.inputs){$current=Get-ArtifactIdentity $identity.path;if($current.sha256 -cne $identity.sha256 -or $current.bytes -ne $identity.bytes){throw 'Whole-checker input changed before shared-context qualification'}};if(($Stages|Sort-Object)-join ',' -cne '1,2'){throw 'Both source-built stages are required'}}
$mapping=[pscustomobject]@{procedures=@{};types=@{}};foreach($p in $prior.mapping.procedures.PSObject.Properties){$mapping.procedures[$p.Name]=$p.Value};foreach($p in $prior.mapping.types.PSObject.Properties){$mapping.types[$p.Name]=$p.Value}
$out=Join-Path $repo ('bootstrap/out/semantic-sharing/'+[guid]::NewGuid().ToString('N'));[void][IO.Directory]::CreateDirectory($out);$utf8=[Text.UTF8Encoding]::new($false)
$nativeHome=$NativeFixtureDirectory
# Inputs are test expectations/helpers, not candidate-derived answers.
$resource=[IO.File]::ReadAllText((Join-Path $nativeHome 'resource-probe.c'));$match=[regex]::Match($resource,'(?s)static int exact_small_result\(.*?(?=static int recover\()');if(-not $match.Success){throw 'Independent complete small-result oracle not found'};$literal=[regex]::Match($resource,'(?m)^static const char valid_source\[\].*$').Value;if(-not $literal){throw 'Independent small source not found'}
[IO.File]::WriteAllText((Join-Path $out 'exact-small.h'),$literal+"`n"+$match.Value,$utf8)
foreach($pair in @(@((Join-Path $nativeHome 'probe.c'),'base-probe.c'),@((Join-Path $nativeHome 'scalar-complete.h'),'scalar-complete.h'),@((Join-Path $nativeHome 'project-resource.h'),'project-resource.h'),@((Join-Path $RunPath 'scalar-source.h'),'scalar-source.h'),@((Join-Path $PSScriptRoot 'probe.c'),'four-probe.c'),@((Join-Path $PSScriptRoot 'EXPECTATIONS.md'),'EXPECTATIONS.md'))){[IO.File]::Copy($pair[0],(Join-Path $out $pair[1]))}
$commands=@();$rows=@();$success=$false;$failure=$null;$inputs=@((Get-ArtifactIdentity (Join-Path $RunPath 'report.json')),(Get-ArtifactIdentity (Join-Path $nativeHome 'resource-probe.c')),(Get-ArtifactIdentity (Join-Path $nativeHome 'project-resource.h')),(Get-ArtifactIdentity (Join-Path $nativeHome 'probe.c')),(Get-ArtifactIdentity (Join-Path $RunPath 'runtime-whole.o')),(Get-ArtifactIdentity $PSCommandPath),(Get-ArtifactIdentity (Join-Path $PSScriptRoot 'probe.c')))
try{
 foreach($stage in $Stages){
  $original=Join-Path $RunPath 'whole-native.ll';if($stage -eq 1){$candidates=@(Get-ChildItem $RunPath -Directory|Where-Object Name -Like 'stage1-*'|ForEach-Object {Join-Path $_.FullName 'whole-native.ll'}|Where-Object {[IO.File]::Exists($_)});if($candidates.Count -ne 1){throw 'Exact stage1 native LLVM snapshot required'};$original=$candidates[0]}
  $raw=[IO.File]::ReadAllText($original);$inputs+=Get-ArtifactIdentity $original;$adapter=[Text.StringBuilder]::new();Add-FoundationBinding $adapter $raw $mapping 'four_bind_body' 'TryBindSemanticModule' 'i1' 'ptr'
  [void]$adapter.AppendLine("declare i32 @four_bind(ptr)`ndefine i1 @four_bind_bridge(ptr %work) {`n %status = call i32 @four_bind(ptr %work)`n %accepted = icmp ne i32 %status, 0`n ret i1 %accepted`n}")
  $call='call i1 @'+$mapping.procedures.TryBindSemanticModule+'(';if([regex]::Matches($raw,[regex]::Escape($call)).Count -ne 1){throw 'Exactly one admitted binder call must be interposed'};$raw=$raw.Replace($call,'call i1 @four_bind_bridge(')
  $ir=Join-Path $out ('stage'+$stage+'.ll');[IO.File]::WriteAllText($ir,$raw+"`n"+$adapter.ToString(),$utf8)
  $object=Join-Path $out ('stage'+$stage+'.o');$compile=Invoke-BoundedProcess $prior.selection.clang.path @('--target=x86_64-w64-windows-gnu','-O2','-c','-x','ir',$ir,'-o',$object) $repo 150;$commands+=,$compile;if($compile.timedOut -or $compile.exit -ne 0){throw $compile.stderr}
  foreach($control in @('','VALUE','OVERLAP')){$exe=Join-Path $out ('stage'+$stage+$(if($control){'-'+$control.ToLowerInvariant()})+'.exe');$defines=@();if($control -eq 'VALUE'){$defines=@('-DNEGATIVE_RESOURCE_SMALL')};if($control -eq 'OVERLAP'){$defines=@('-DNEGATIVE_FOUR_OVERLAP')};$args=@('--target=x86_64-w64-windows-gnu','-O2','-I',$out,'-I',(Join-Path $repo 'bootstrap/runtime'),'-x','c',(Join-Path $out 'four-probe.c'),'-std=c11','-Wall','-Wextra','-Werror')+$defines+@('-x','none',$object,(Join-Path $RunPath 'runtime-whole.o'),$prior.selection.unicodeRuntime.path,'-o',$exe)
   $link=Invoke-BoundedProcess $prior.selection.clang.path $args $repo 150;$commands+=,$link;if($link.timedOut -or $link.exit -ne 0){throw $link.stderr}
   $native=Invoke-BoundedProcess $exe @() $repo 120;$commands+=,$native;$rows+=@{stage=$stage;control=$control;native=$native;originalLLVM=(Get-ArtifactIdentity $original)}
   if($control){if($native.timedOut -or $native.exit -ne 1 -or $native.stderr -notmatch 'whole checker assertion'){throw 'Four-context corruption control not rejected'}}else{if($native.timedOut -or $native.exit -ne 0 -or $native.stderr -cne '' -or $native.stdout -notmatch 'PASS four simultaneous whole contexts assertions:'){throw "Four-context actual check failed exit$($native.exit): $($native.stderr)"}}
  }
 }
 $positive=@($rows|Where-Object control -CEQ '');if($positive.Count -eq 2 -and $positive[0].originalLLVM.sha256 -cne $positive[1].originalLLVM.sha256){throw 'Both source-built raw snapshots differ'}
 $success=$true
}catch{$failure=$_.Exception.Message}
$report=@{success=$success;failure=$failure;diagnosticOnly=[bool]$DiagnosticOnly;qualified=($success -and -not $DiagnosticOnly);inputs=$inputs;rows=$rows;commands=$commands;artifacts=@(Get-ChildItem $out -File|ForEach-Object {Get-ArtifactIdentity $_.FullName});scope='Intact full coordinators/real inner UBE CallNew workers; C native outer callers and scalar barrier only. Exact independent small result oracle reused verbatim. Current whole-source inputs are rechecked by default; DiagnosticOnly cannot qualify a final cohort.'};$report|ConvertTo-Json -Depth 20|Set-Content (Join-Path $out 'report.json') -Encoding UTF8
Write-Output "Evidence: $out/report.json";foreach($row in $rows){Write-Output ('stage'+$row.stage+' '+$row.control+' exit'+$row.native.exit+' '+$row.native.stdout)}
if(-not $success){throw $failure}
